import{_ as t}from"./chunks/difficulty_medium.CPaRe1i7.js";import{_ as i}from"./chunks/remote_control.ss1psCxn.js";import{_ as o}from"./chunks/stabilized_mc.i746iZED.js";import{_ as a,o as l,c as r,al as s}from"./chunks/framework.7vp1BMOE.js";const g=JSON.parse('{"title":"Manual/Stabilized Mode (Multicopter)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_modes_mc/manual_stabilized.md","filePath":"zh/flight_modes_mc/manual_stabilized.md"}'),n={name:"zh/flight_modes_mc/manual_stabilized.md"};function d(c,e,h,m,u,p){return l(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="manual-stabilized-mode-multicopter" tabindex="-1">Manual/Stabilized Mode (Multicopter) <a class="header-anchor" href="#manual-stabilized-mode-multicopter" aria-label="Permalink to &quot;Manual/Stabilized Mode (Multicopter)&quot;">​</a></h1><p><img src="'+t+'" title="Medium difficulty to fly" width="30px"> <img src="'+i+'" title="Manual/Remote control required" width="30px"> </p><p>The <em>Stabilized</em> manual mode stabilizes and levels the multicopter when the RC control sticks are centred. To move/fly the vehicle you move the sticks outside of the centre.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PX4 has separate MC <em>Manual</em> and <em>Stabilized</em> navigation states, which correspond to separate flight modes that can be set (and displayed via MAVLink). These modes behave identically in flight, but have different arming requirements — see <a href="#mode-requirements">Mode Requirements</a> below.</p></div><p>When sticks are outside the centre, the roll and pitch sticks control the <em>angle</em> of the vehicle (attitude) around the respective axes, the yaw stick controls the rate of rotation above the horizontal plane, and the throttle controls altitude/speed.</p><p>一旦释放摇杆，它们将会返回中心停顿区。 一旦横滚和俯仰摇杆居中，多旋翼无人机将平稳并停止运动。 The vehicle will then hover in place/maintain altitude - provided it is properly balanced, throttle is set appropriately (see <a href="#parameters">below</a>), and no external forces are applied (e.g. wind). 飞行器将朝着任何风的方向漂移，您必须控制油门以保持高度。</p><p><img src="'+o+'" alt="MC Manual Flight"></p><h2 id="技术描述" tabindex="-1">技术描述 <a class="header-anchor" href="#技术描述" aria-label="Permalink to &quot;技术描述&quot;">​</a></h2><p>RC mode where centered sticks level vehicle.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><a href="./../flight_modes_mc/altitude">Altitude mode</a> additionally stabilizes the vehicle altitude when sticks are centred, and <a href="./../flight_modes_mc/position">Position mode</a> stabilizes both altitude and position over ground.</p></div><p>飞手的输入通过横滚和俯仰角度以及偏航角速率指令传递给自驾仪。 Throttle is rescaled (see <a href="#parameters">below</a>) and passed directly to control allocation. 自动驾驶仪控制着飞机的姿态角，这意味着当 RC 摇杆居中时自驾仪调整飞机的滚转和俯仰角为零（从而实现飞机姿态的改平）。 自动驾驶仪不能补偿由于风（或其他来源）引起的漂移。</p><ul><li>Centered sticks: <ul><li>Roll/Pitch sticks level vehicle.</li></ul></li><li>外部中心： <ul><li>Roll/Pitch sticks control tilt angle in those orientations, resulting in corresponding left-right and forward-back movement.</li><li>Throttle stick controls up/down speed (and movement speed in other axes).</li><li>偏航摇杆控制水平面上方的角度旋转速率。</li></ul></li><li>Manual control input is required (such as RC control, joystick). <ul><li>Roll, Pitch: Assistance from autopilot to stabilize the attitude. Position of RC stick maps to the orientation of vehicle.</li><li>Throttle: Manual control via RC sticks. RC input is sent directly to control allocation.</li><li>Yaw: Assistance from autopilot to stabilize the attitude rate. Position of RC stick maps to the rate of rotation of vehicle in that orientation.</li></ul></li></ul><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_manual_control"><code>mode_req_manual_control</code></a> — Requires stick input</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These requirements are form arming in Stabilized mode.</p></div><h3 id="mode-requirements-1" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements-1" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_manual_control"><code>mode_req_manual_control</code></a> — Requires stick input</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>These requirements are for arming in Manual mode.</p></div><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>描述</th></tr></thead><tbody><tr><td><a id="MPC_THR_HOVER"></a><a href="./../advanced_config/parameter_reference#MPC_THR_HOVER">MPC_THR_HOVER</a></td><td>Hover throttle that is output when the throttle stick is centered and <code>MPC_THR_CURVE</code> is set to default.</td></tr><tr><td><a id="MPC_THR_CURVE"></a><a href="./../advanced_config/parameter_reference#MPC_THR_CURVE">MPC_THR_CURVE</a></td><td>定义油门缩放比例。 By default this is set to <strong>Rescale to hover thrust</strong>, which means that when the throttle stick is centered the configured hover throttle is output (<code>MPC_THR_HOVER</code>) and the stick input is linearly rescaled below and above that (allowing for a smooth transition between Stabilized and Altitude/Position control). <br>在动力很强的机体上，悬停油门可能非常低（例如低于 20％），因此重新调整会使油门输入变形 - 对应上面举例， 80％ 的推力将仅由摇杆输入的中位以上部分控制，20％ 的推力由中位以下的部分来控制。 If needed <code>MPC_THR_CURVE</code> can be set to <strong>No Rescale</strong> so that there is no rescaling (stick input to throttle mapping is independent of <code>MPC_THR_HOVER</code>).</td></tr></tbody></table>',22)])])}const R=a(n,[["render",d]]);export{g as __pageData,R as default};
